<label><?= $mode==='signup'?'Email':'Email or username' ?><input type="<?= $mode==='signup'?'email':'text' ?>" name="email" value="<?= bb_h($_POST['email'] ?? '') ?>" autocomplete="<?= $mode==='signup'?'email':'username' ?>" required maxlength="255"></label>
